`timescale 1ns/1ps
// ===========================================================================
// tb_crc_bit.v -- bit-serial CRC assist (v2/src/crc_bit.v).
//
// Same five protocol configurations and the same 16-byte stream as the study
// bench (studies/hybrid/tb/tb_crc.v, vectors regenerated by gen_crc_vectors.py,
// which asserts every published catalogue check value first).  The study bench
// drove the byte-at-a-time block; the hybrid build ships the bit-serial form
// (results/hybrid_area.md 2.1: 21,152.96 um2 vs 35,035.01), so this bench
// drives one LFSR step per clock -- 8 clocks per byte -- instead of byte_en.
//
// Bit order: cfg_data[7] = LSB-first, which is what a reflected CRC needs; the
// caller shifts the byte out, so the block does not store that bit.
// ===========================================================================
module tb_crc_bit;
  localparam integer NC = 5;
  localparam integer NB = 16;

  reg clk = 0;
  reg rst_n = 0;
  reg cfg_we = 0;
  reg [1:0] cfg_sel = 0;
  reg [31:0] cfg_data = 0;
  reg start = 0, bit_en = 0, bit_in = 0;
  wire [31:0] crc_out;
  wire crc_bit_out, refl_o;

  reg [31:0] m_init [0:NC-1];
  reg [31:0] m_poly [0:NC-1];
  reg [31:0] m_xor  [0:NC-1];
  reg [31:0] m_wsel [0:NC-1];
  reg [31:0] m_exp  [0:NC-1];
  reg [7:0]  bytes  [0:NB-1];

  integer c, i, b, errs = 0;

  crc_bit dut (
    .clk(clk), .rst_n(rst_n),
    .cfg_we(cfg_we), .cfg_sel(cfg_sel), .cfg_data(cfg_data),
    .start(start), .bit_en(bit_en), .bit_in(bit_in),
    .crc_out(crc_out), .crc_bit_out(crc_bit_out), .refl_out(refl_o)
  );

  always #5 clk = ~clk;

  task cfgw(input [1:0] s, input [31:0] d);
    begin
      @(negedge clk); cfg_we = 1; cfg_sel = s; cfg_data = d;
      @(negedge clk); cfg_we = 0;
    end
  endtask

  task fail(input [255:0] what, input [31:0] got, input [31:0] want);
    begin
      errs = errs + 1;
      $display("FAIL %0s: got 0x%08x want 0x%08x", what, got, want);
    end
  endtask

  initial begin
    $readmemh("crc_init.hex", m_init);
    $readmemh("crc_poly.hex", m_poly);
    $readmemh("crc_xor.hex",  m_xor);
    $readmemh("crc_wsel.hex", m_wsel);
    $readmemh("crc_exp.hex",  m_exp);
    $readmemh("crc_bytes.hex", bytes);

    repeat (3) @(negedge clk);
    rst_n = 1;
    repeat (2) @(negedge clk);

    for (c = 0; c < NC; c = c + 1) begin
      cfgw(2'd0, m_init[c]);
      cfgw(2'd1, m_poly[c]);
      cfgw(2'd2, m_wsel[c]);
      cfgw(2'd3, m_xor[c]);

      @(negedge clk); start = 1;
      @(negedge clk); start = 0;
      if (crc_out !== (m_init[c] ^ m_xor[c]))
        fail("post-start seed", crc_out, m_init[c] ^ m_xor[c]);

      for (i = 0; i < NB; i = i + 1) begin
        for (b = 0; b < 8; b = b + 1) begin
          @(negedge clk);
          bit_in = m_wsel[c][7] ? bytes[i][b] : bytes[i][7 - b];
          bit_en = 1;
        end
      end
      @(negedge clk);
      bit_en = 0;
      @(negedge clk);
      if (crc_out !== m_exp[c])
        fail("stream", crc_out, m_exp[c]);
      else
        $display("PASS config %0d (width %0d, refl %0d, lsb %0d): crc=0x%08x",
                 c, m_wsel[c][5:0], m_wsel[c][6], m_wsel[c][7], crc_out);
      if (refl_o !== m_wsel[c][6]) begin
        errs = errs + 1;
        $display("FAIL config %0d: refl_out %b want %b", c, refl_o, m_wsel[c][6]);
      end
    end

    if (errs == 0) $display("TB_CRC_BIT PASS");
    else           $display("TB_CRC_BIT FAIL (%0d errors)", errs);
    $finish;
  end

  initial begin
    #200000;
    $display("TB_CRC_BIT FAIL (timeout)");
    $finish;
  end
endmodule
